import hashlib
import hmac
import os
import re
import socket
import sqlite3
import time
from urllib.parse import urlparse, urljoin
from flask import Flask, request, jsonify, session, g
import requests

app = Flask(__name__)
app.secret_key = os.urandom(32)

DATABASE = ':memory:'
ALLOWED_SCHEMES = {'https'}
BLOCKED_HOSTS = re.compile(
    r'^(127\.|10\.|172\.(1[6-9]|2[0-9]|3[01])\.|192\.168\.|0\.|169\.254\.|localhost|\[::1\]|metadata\.google)'
)
ALLOWED_CONTENT_TYPES = {'application/json', 'text/plain', 'text/html'}
MAX_REDIRECTS = 5
REQUEST_TIMEOUT = 10

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.execute('CREATE TABLE IF NOT EXISTS bookmarks (id INTEGER PRIMARY KEY, user_id TEXT, url TEXT, title TEXT, preview TEXT)')
        g.db.execute('CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, api_key_hash TEXT)')
        g.db.commit()
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def validate_api_key(api_key):
    if not api_key or len(api_key) < 32:
        return None
    db = get_db()
    key_hash = hashlib.sha256(api_key.encode()).hexdigest()
    row = db.execute('SELECT id FROM users WHERE api_key_hash = ?', (key_hash,)).fetchone()
    return row[0] if row else None

def resolve_hostname(hostname):
    """Resolve hostname and check if it points to an internal IP."""
    try:
        addr_info = socket.getaddrinfo(hostname, None, socket.AF_INET)
        for family, socktype, proto, canonname, sockaddr in addr_info:
            ip = sockaddr[0]
            parts = ip.split('.')
            if len(parts) == 4:
                octets = [int(p) for p in parts]
                if octets[0] in (10, 127, 0) or \
                   (octets[0] == 172 and 16 <= octets[1] <= 31) or \
                   (octets[0] == 192 and octets[1] == 168) or \
                   (octets[0] == 169 and octets[1] == 254):
                    return False
        return True
    except (socket.gaierror, ValueError, OSError):
        return False

def is_safe_url(url):
    """Validate URL is safe to fetch - checks scheme, host against blocklist, and DNS resolution."""
    try:
        parsed = urlparse(url)
        if parsed.scheme not in ALLOWED_SCHEMES:
            return False
        hostname = parsed.hostname
        if not hostname:
            return False
        if BLOCKED_HOSTS.match(hostname):
            return False
        # Block numeric IPs that could be internal
        if re.match(r'^\d+\.\d+\.\d+\.\d+$', hostname):
            parts = hostname.split('.')
            if len(parts) == 4:
                try:
                    octets = [int(p) for p in parts]
                    if octets[0] in (10, 127, 0) or \
                       (octets[0] == 172 and 16 <= octets[1] <= 31) or \
                       (octets[0] == 192 and octets[1] == 168) or \
                       (octets[0] == 169 and octets[1] == 254):
                        return False
                except ValueError:
                    return False
        # DNS resolution check - verify hostname doesn't resolve to internal IP
        if not resolve_hostname(hostname):
            return False
        return True
    except Exception:
        return False

def fetch_url_content(url):
    """Fetch URL content with redirect handling and full validation at each step."""
    if not is_safe_url(url):
        return None, "URL failed safety validation"

    current_url = url
    visited = set()

    for i in range(MAX_REDIRECTS):
        if current_url in visited:
            return None, "Redirect loop detected"
        visited.add(current_url)

        # Validate EVERY URL before fetching, including redirect targets
        if not is_safe_url(current_url):
            return None, "Redirect target failed safety validation"

        try:
            resp = requests.get(
                current_url,
                allow_redirects=False,
                timeout=REQUEST_TIMEOUT,
                headers={'User-Agent': 'BookmarkBot/1.0'}
            )
        except requests.RequestException as e:
            return None, f"Request failed: {str(e)}"

        if resp.status_code in (301, 302, 303, 307, 308):
            location = resp.headers.get('Location', '')
            # Resolve relative redirects
            next_url = urljoin(current_url, location)
            # Full validation of redirect target including DNS resolution
            if not is_safe_url(next_url):
                return None, "Redirect to unsafe destination"
            current_url = next_url
            continue

        if resp.status_code == 200:
            content_type = resp.headers.get('Content-Type', '').split(';')[0].strip()
            if content_type not in ALLOWED_CONTENT_TYPES:
                return None, "Disallowed content type"
            return resp.text[:4096], None
        else:
            return None, f"HTTP {resp.status_code}"

    return None, "Too many redirects"

@app.route('/api/bookmark', methods=['POST'])
def create_bookmark():
    api_key = request.headers.get('X-API-Key')
    user_id = validate_api_key(api_key)
    if not user_id:
        return jsonify({'error': 'Unauthorized'}), 401

    data = request.get_json()
    if not data or 'url' not in data:
        return jsonify({'error': 'Missing url field'}), 400

    url = data['url']
    title = data.get('title', 'Untitled')

    if not isinstance(url, str) or len(url) > 2048:
        return jsonify({'error': 'Invalid URL'}), 400

    if not is_safe_url(url):
        return jsonify({'error': 'URL not allowed'}), 403

    # Fetch preview
    preview, error = fetch_url_content(url)
    if error:
        preview = f"Could not fetch: {error}"

    db = get_db()
    db.execute(
        'INSERT INTO bookmarks (user_id, url, title, preview) VALUES (?, ?, ?, ?)',
        (user_id, url, title[:200], preview)
    )
    db.commit()

    return jsonify({'status': 'created', 'preview': preview[:500]}), 201

@app.route('/api/bookmarks', methods=['GET'])
def list_bookmarks():
    api_key = request.headers.get('X-API-Key')
    user_id = validate_api_key(api_key)
    if not user_id:
        return jsonify({'error': 'Unauthorized'}), 401

    db = get_db()
    rows = db.execute(
        'SELECT id, url, title, preview FROM bookmarks WHERE user_id = ?',
        (user_id,)
    ).fetchall()

    return jsonify([{'id': r[0], 'url': r[1], 'title': r[2], 'preview': r[3]} for r in rows])

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080)
